/**
 * Returns the domain's outline as a closed `[lon, lat]` ring: the precomputed
 * data-shape footprint when one exists (NULL-padded grids whose real data region
 * is smaller than the grid box), otherwise the grid's boundary polygon
 * (`getBoundaryPolygon`). Rings unwrap longitudes like `getBoundaryPolygon`:
 * one enclosing a pole ends 360° east of where it starts.
 */
export const getDomainBoundary = (domain: Domain): Array<[number, number]> =>
	DOMAIN_FOOTPRINTS[domain.value] ?? GridFactory.create(domain.grid, null).getBoundaryPolygon();
